import type { Ref } from 'vue'
import { useNuxtApp, useState } from '#imports'
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore virtual module generated by this module's `setup()`
import { useCapacitor } from '#dashboard/optional'
import type { DashboardPlatform } from '../../../types'

/**
 * `mobile` inside the native shell of `@frigear-nu/mobile` (`useCapacitor().isNative`), `web` everywhere else,
 * including the server and a browser without mobile installed.
 *
 * The server always renders `web`. When the page was server-rendered (mobile with `spa: false`), the client switches
 * to `mobile` only once hydration is done, so the first client render matches the server's HTML.
 */
export function useDashboardPlatform(): Ref<DashboardPlatform> {
  const nuxtApp = useNuxtApp()
  const platform = useState<DashboardPlatform>('dashboard:platform', () => 'web')
  if (import.meta.client && useCapacitor) {
    const detected: DashboardPlatform = useCapacitor().isNative ? 'mobile' : 'web'
    if (platform.value !== detected) {
      const apply = () => {
        platform.value = detected
      }
      if (nuxtApp.isHydrating) nuxtApp.hooks.hookOnce('app:suspense:resolve', apply)
      else apply()
    }
  }
  return platform
}
